<?php $title='Invoice';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1><?=e($invoice['invoice_number'])?></h1><p><?=e($invoice['status'])?></p></div><div class="invoice-total"><?=money((float)$invoice['grand_total'])?></div></div><section class="grid two"><div class="panel"><h2>Invoice details</h2><dl><dt>Created</dt><dd><?=e($invoice['created_date'])?></dd><dt>Due</dt><dd><?=e($invoice['due_date'])?></dd><dt>Total paid</dt><dd><?=money((float)$invoice['total_paid'])?></dd><dt>Balance</dt><dd><?=money((float)$invoice['balance'])?></dd></dl></div><div class="panel"><h2>Record payment</h2><?php if((float)$invoice['balance']>0):?><form method="post" action="<?=route('invoice.payment',['id'=>$invoice['id']])?>"><?=csrf_field()?><label>Amount<input type="number" step="0.01" name="amount" max="<?=e($invoice['balance'])?>" required></label><label>Method<select name="payment_method"><option>card</option><option>bank</option><option>cash</option><option>check</option><option>other</option></select></label><label>Reference<input name="reference_no"></label><button class="primary">Record payment</button></form><?php else:?><div class="success">Paid in full.</div><?php endif;?></div></section><section class="panel"><h2>Items</h2><table><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr><?php foreach($invoice['items'] as $it):?><tr><td><?=e($it['description'])?></td><td><?=e($it['quantity'])?></td><td><?=money((float)$it['unit_price'])?></td><td><?=money((float)$it['total'])?></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/../layouts/footer.php';?>
